import Image from 'next/image'
import Link from 'next/link'
import { ArrowRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type AboutGalleryImage = {
  src: string
  alt: string
}

export type AboutGalleryProps = {
  eyebrow?: string
  title: string
  description: string
  images: readonly AboutGalleryImage[]
  variant?: 'mosaic' | 'gallery' | 'editorial'
  stats?: readonly { value: string; label: string }[]
  action?: { label: string; href: string }
  mediaPosition?: 'left' | 'right'
  className?: string
}

export function AboutGallery({
  eyebrow,
  title,
  description,
  images,
  variant = 'mosaic',
  stats = [],
  action,
  mediaPosition = 'left',
  className,
}: AboutGalleryProps) {
  const visibleImages = images.slice(0, variant === 'gallery' ? 4 : 3)

  return (
    <section className={cn('overflow-hidden py-16 md:py-24', className)}>
      <div className="container grid items-center gap-10 lg:grid-cols-2 lg:gap-16">
        <div
          className={cn(
            'grid min-h-[460px] gap-3',
            variant === 'mosaic' && 'grid-cols-2 grid-rows-2',
            variant === 'gallery' && 'grid-cols-2 grid-rows-2',
            variant === 'editorial' && 'grid-cols-[1fr_.48fr] grid-rows-2',
            mediaPosition === 'right' && 'lg:order-2',
          )}
        >
          {visibleImages.map((image, index) => (
            <figure
              key={`${image.src}-${index}`}
              className={cn(
                'relative min-h-52 overflow-hidden rounded-3xl bg-muted',
                variant === 'mosaic' && index === 0 && 'row-span-2',
                variant === 'editorial' && index === 0 && 'row-span-2',
              )}
            >
              <Image
                src={image.src}
                alt={image.alt}
                fill
                className="object-cover transition-transform duration-700 hover:scale-105"
                sizes="(min-width: 1024px) 30vw, 50vw"
              />
            </figure>
          ))}
        </div>

        <div className={cn('max-w-xl', mediaPosition === 'right' && 'lg:order-1')}>
          {eyebrow ? (
            <p className="text-xs font-bold uppercase tracking-[0.2em] text-primary">{eyebrow}</p>
          ) : null}
          <h2 className="mt-4 text-3xl font-bold tracking-tight md:text-5xl">{title}</h2>
          <p className="mt-6 text-base leading-8 text-muted-foreground">{description}</p>

          {stats.length ? (
            <dl className="mt-8 grid grid-cols-2 gap-5 border-y py-6 sm:grid-cols-3">
              {stats.slice(0, 3).map((stat) => (
                <div key={`${stat.value}-${stat.label}`}>
                  <dt className="text-xs text-muted-foreground">{stat.label}</dt>
                  <dd className="mt-1 text-2xl font-bold">{stat.value}</dd>
                </div>
              ))}
            </dl>
          ) : null}

          {action ? (
            <Link
              href={action.href}
              className="mt-8 inline-flex items-center gap-2 rounded-sm font-semibold text-primary focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
            >
              {action.label}
              <ArrowRight className="h-4 w-4" aria-hidden />
            </Link>
          ) : null}
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'
import Link from 'next/link'
import { ArrowUpRight } from 'lucide-react'

import { cn } from '@/lib/utils'

export type CategoryMosaicItem = {
  id: string
  label: string
  href: string
  image: { src: string; alt: string }
  size?: 'standard' | 'tall' | 'wide'
}

export type CategoryMosaicProps = {
  items: readonly CategoryMosaicItem[]
  title?: string
  description?: string
  labelStyle?: 'card' | 'glass' | 'plain'
  rounded?: boolean
  className?: string
}

export function CategoryMosaic({
  items,
  title,
  description,
  labelStyle = 'card',
  rounded = true,
  className,
}: CategoryMosaicProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'category-mosaic-title' : undefined}
    >
      <div className="container">
        {title || description ? (
          <header className="mb-10 max-w-2xl">
            {title ? (
              <h2
                id="category-mosaic-title"
                className="text-3xl font-bold tracking-tight md:text-5xl"
              >
                {title}
              </h2>
            ) : null}
            {description ? (
              <p className="mt-4 text-base leading-7 text-muted-foreground">{description}</p>
            ) : null}
          </header>
        ) : null}

        <div className="grid auto-rows-[220px] gap-4 sm:grid-cols-2 lg:grid-cols-4">
          {items.map((item, index) => {
            const inferredSize = item.size ?? (index < 2 ? 'tall' : 'standard')

            return (
              <Link
                href={item.href}
                key={item.id}
                className={cn(
                  'group relative isolate flex overflow-hidden bg-muted focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2',
                  rounded && 'rounded-2xl',
                  inferredSize === 'tall' && 'sm:row-span-2',
                  inferredSize === 'wide' && 'sm:col-span-2',
                )}
              >
                <Image
                  src={item.image.src}
                  alt={item.image.alt}
                  fill
                  className="object-cover transition-transform duration-700 group-hover:scale-105"
                  sizes="(min-width: 1024px) 25vw, (min-width: 640px) 50vw, 100vw"
                />
                <span className="absolute inset-0 bg-black/10 transition group-hover:bg-black/25" />
                <span
                  className={cn(
                    'relative m-auto inline-flex items-center gap-2 px-5 py-3 text-xs font-bold uppercase tracking-[0.24em] transition duration-300 group-hover:scale-105',
                    labelStyle === 'card' && 'bg-white text-slate-950 shadow-xl',
                    labelStyle === 'glass' &&
                      'border border-white/30 bg-black/25 text-white backdrop-blur-md',
                    labelStyle === 'plain' && 'text-white drop-shadow-lg',
                    rounded && labelStyle !== 'plain' && 'rounded-lg',
                  )}
                >
                  {item.label}
                  <ArrowUpRight
                    className="h-3.5 w-3.5 opacity-0 transition group-hover:opacity-100"
                    aria-hidden
                  />
                </span>
              </Link>
            )
          })}
        </div>
      </div>
    </section>
  )
}

import Image from 'next/image'
import type { HTMLAttributes } from 'react'
import { cn } from '@/lib/utils'

export type GalleryGridItem = {
  src: string
  alt: string
  title?: string
  description?: string
  href?: string
  width?: number
  height?: number
}

export interface GalleryGridProps extends Omit<HTMLAttributes<HTMLElement>, 'children'> {
  items: readonly GalleryGridItem[]
  columns?: 2 | 3 | 4
  aspect?: 'square' | 'video' | 'portrait'
  variant?: 'grid' | 'masonry'
  emptyMessage?: string
}

export function GalleryGrid({
  items,
  columns = 3,
  aspect = 'square',
  variant = 'grid',
  emptyMessage = 'Nenhuma imagem disponível.',
  className,
  ...props
}: GalleryGridProps) {
  const columnsClass = {
    2: 'md:grid-cols-2',
    3: 'md:grid-cols-2 lg:grid-cols-3',
    4: 'md:grid-cols-2 lg:grid-cols-4',
  }[columns]
  const aspectClass = { square: 'aspect-square', video: 'aspect-video', portrait: 'aspect-[3/4]' }[
    aspect
  ]

  if (!items.length) {
    return (
      <div
        className={cn(
          'rounded-2xl border border-dashed p-8 text-center text-muted-foreground',
          className,
        )}
      >
        {emptyMessage}
      </div>
    )
  }

  return (
    <section
      aria-label="Galeria de imagens"
      className={cn('grid grid-cols-1 gap-4', columnsClass, className)}
      {...props}
    >
      {items.map((item, index) => {
        const content = (
          <>
            <div
              className={cn(
                'relative overflow-hidden rounded-2xl bg-muted',
                variant === 'grid' && aspectClass,
              )}
            >
              <Image
                src={item.src}
                alt={item.alt}
                width={item.width ?? 900}
                height={item.height ?? 900}
                sizes={`(min-width: 1024px) ${Math.round(100 / columns)}vw, (min-width: 768px) 50vw, 100vw`}
                className={cn(
                  'h-full w-full object-cover transition duration-500 group-hover:scale-105',
                  variant === 'masonry' && 'h-auto',
                )}
              />
              {(item.title || item.description) && variant === 'grid' ? (
                <div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/80 to-transparent p-5 pt-16 text-white">
                  {item.title ? <h3 className="font-semibold">{item.title}</h3> : null}
                  {item.description ? (
                    <p className="mt-1 text-sm text-white/80">{item.description}</p>
                  ) : null}
                </div>
              ) : null}
            </div>
            {(item.title || item.description) && variant === 'masonry' ? (
              <div className="px-1 pt-3">
                {item.title ? <h3 className="font-semibold">{item.title}</h3> : null}
                {item.description ? (
                  <p className="mt-1 text-sm text-muted-foreground">{item.description}</p>
                ) : null}
              </div>
            ) : null}
          </>
        )
        return item.href ? (
          <a
            key={`${item.src}-${index}`}
            href={item.href}
            className="group rounded-2xl focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
          >
            {content}
          </a>
        ) : (
          <article key={`${item.src}-${index}`} className="group">
            {content}
          </article>
        )
      })}
    </section>
  )
}

import type { CSSProperties } from 'react'
import { ArrowUpRight, MapPin } from 'lucide-react'
import { cn } from '@/lib/utils'

export type MapEmbedSectionProps = {
  /** Endereço ou termo usado no Google Maps. */
  query: string
  title?: string
  description?: string
  eyebrow?: string
  address?: string
  directionsHref?: string
  directionsLabel?: string
  height?: number
  className?: string
}

export function MapEmbedSection({
  query,
  title,
  description,
  eyebrow,
  address,
  directionsHref,
  directionsLabel = 'Como chegar',
  height = 450,
  className,
}: MapEmbedSectionProps) {
  return (
    <section
      className={cn('py-16 md:py-24', className)}
      aria-labelledby={title ? 'map-title' : undefined}
    >
      <div className="container">
        {title ? (
          <div className="mb-10 max-w-2xl">
            {eyebrow ? (
              <p className="text-sm font-semibold uppercase tracking-[0.2em] text-primary">
                {eyebrow}
              </p>
            ) : null}
            <h2
              id="map-title"
              className={cn('text-3xl font-bold tracking-tight md:text-4xl', eyebrow && 'mt-3')}
            >
              {title}
            </h2>
            {description ? <p className="mt-4 text-muted-foreground">{description}</p> : null}
          </div>
        ) : null}
        <div className="overflow-hidden rounded-3xl border bg-muted shadow-sm">
          <iframe
            title={`Mapa: ${query}`}
            src={`https://www.google.com/maps?q=${encodeURIComponent(query)}&output=embed`}
            className="block h-80 w-full border-0 md:h-[var(--map-height)]"
            style={{ '--map-height': `${height}px` } as CSSProperties}
            loading="lazy"
            referrerPolicy="no-referrer-when-downgrade"
            allowFullScreen
          />
          {address ? (
            <div className="flex flex-col gap-3 border-t bg-card px-5 py-4 sm:flex-row sm:items-center sm:justify-between md:px-6">
              <p className="flex items-start gap-2 text-sm font-medium">
                <MapPin className="mt-0.5 h-4 w-4 shrink-0 text-primary" aria-hidden="true" />
                {address}
              </p>
              {directionsHref ? (
                <a
                  href={directionsHref}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex shrink-0 items-center gap-1 text-sm font-semibold text-primary hover:underline"
                >
                  {directionsLabel}
                  <ArrowUpRight className="h-4 w-4" aria-hidden="true" />
                  <span className="sr-only">(abre em nova aba)</span>
                </a>
              ) : null}
            </div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

'use client'

import Image from 'next/image'
import { A11y, Keyboard, Navigation, Pagination } from 'swiper/modules'
import { Swiper, SwiperSlide } from 'swiper/react'
import { Quote } from 'lucide-react'
import type { Testimonial } from './TestimonialsGrid'
import { cn } from '@/lib/utils'
import 'swiper/css'
import 'swiper/css/navigation'
import 'swiper/css/pagination'

export type TestimonialsCarouselProps = {
  title?: string
  testimonials: Testimonial[]
  className?: string
  label?: string
}

export function TestimonialsCarousel({
  title,
  testimonials,
  className,
  label = 'Depoimentos de clientes',
}: TestimonialsCarouselProps) {
  return (
    <section className={cn('py-16 md:py-24', className)} aria-label={label}>
      <div className="container">
        {title ? (
          <h2 className="mb-10 text-center text-3xl font-bold tracking-tight md:text-4xl">
            {title}
          </h2>
        ) : null}
        <Swiper
          modules={[A11y, Keyboard, Navigation, Pagination]}
          navigation
          pagination={{ clickable: true }}
          keyboard={{ enabled: true }}
          a11y={{ enabled: true }}
          spaceBetween={24}
          slidesPerView={1}
        >
          {testimonials.map((testimonial, index) => (
            <SwiperSlide key={`${testimonial.name}-${index}`}>
              <figure className="mx-auto max-w-3xl px-12 pb-12 text-center">
                <Quote className="mx-auto h-8 w-8 text-primary" aria-hidden="true" />
                <blockquote className="mt-5 text-xl leading-9 md:text-2xl">
                  &ldquo;{testimonial.quote}&rdquo;
                </blockquote>
                <figcaption className="mt-7 flex items-center justify-center gap-3">
                  {testimonial.avatar ? (
                    <Image
                      src={testimonial.avatar}
                      alt=""
                      width={48}
                      height={48}
                      className="h-12 w-12 rounded-full object-cover"
                    />
                  ) : null}
                  <span className="text-left">
                    <span className="block font-semibold">{testimonial.name}</span>
                    <span className="block text-sm text-muted-foreground">
                      {[testimonial.role, testimonial.company].filter(Boolean).join(' · ')}
                    </span>
                  </span>
                </figcaption>
              </figure>
            </SwiperSlide>
          ))}
        </Swiper>
      </div>
    </section>
  )
}

