'use client'

import { useId, useState, type FormEvent, type HTMLAttributes } from 'react'
import { ArrowRight, CheckCircle2 } from 'lucide-react'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { cn } from '@/lib/utils'

export interface NewsletterFormProps extends Omit<HTMLAttributes<HTMLDivElement>, 'onSubmit'> {
  title?: string
  description?: string
  placeholder?: string
  submitLabel?: string
  successMessage?: string
  errorMessage?: string
  variant?: 'inline' | 'card'
  consentLabel?: string
  onSubmit: (email: string) => Promise<void> | void
}

export function NewsletterForm({
  title = 'Receba nossas novidades',
  description,
  placeholder = 'voce@empresa.com',
  submitLabel = 'Inscrever-se',
  successMessage = 'Inscrição realizada com sucesso.',
  errorMessage = 'Não foi possível concluir a inscrição.',
  variant = 'card',
  consentLabel,
  onSubmit,
  className,
  ...props
}: NewsletterFormProps) {
  const id = useId()
  const [status, setStatus] = useState<'idle' | 'loading' | 'success' | 'error'>('idle')

  async function handleSubmit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault()
    const form = event.currentTarget
    const email = String(new FormData(form).get('email') ?? '')
    setStatus('loading')
    try {
      await onSubmit(email)
      setStatus('success')
      form.reset()
    } catch {
      setStatus('error')
    }
  }

  return (
    <div
      className={cn(
        variant === 'card' && 'rounded-2xl border bg-card p-6 shadow-sm md:p-8',
        className,
      )}
      {...props}
    >
      {title ? <h2 className="text-2xl font-bold tracking-tight">{title}</h2> : null}
      {description ? <p className="mt-2 text-muted-foreground">{description}</p> : null}
      <form className="mt-5" onSubmit={handleSubmit}>
        <label htmlFor={id} className="sr-only">
          E-mail
        </label>
        <div
          className={cn('flex gap-2', variant === 'inline' ? 'flex-col sm:flex-row' : 'flex-col')}
        >
          <Input
            id={id}
            name="email"
            type="email"
            autoComplete="email"
            required
            placeholder={placeholder}
            aria-describedby={`${id}-status`}
          />
          <Button type="submit" disabled={status === 'loading'} className="shrink-0">
            {status === 'loading' ? 'Enviando…' : submitLabel}
            {status !== 'loading' ? (
              <ArrowRight className="ml-2 h-4 w-4" aria-hidden="true" />
            ) : null}
          </Button>
        </div>
        {consentLabel ? (
          <label className="mt-3 flex items-start gap-2 text-xs text-muted-foreground">
            <input
              type="checkbox"
              required
              className="mt-0.5 h-4 w-4 rounded border-input accent-primary"
            />
            <span>{consentLabel}</span>
          </label>
        ) : null}
        <div id={`${id}-status`} aria-live="polite" className="mt-3 min-h-5 text-sm">
          {status === 'success' ? (
            <p className="flex items-center gap-2 text-emerald-600">
              <CheckCircle2 className="h-4 w-4" />
              {successMessage}
            </p>
          ) : null}
          {status === 'error' ? <p className="text-destructive">{errorMessage}</p> : null}
        </div>
      </form>
    </div>
  )
}

import type { ReactNode } from 'react'
import Image from 'next/image'

import { HoverButton } from '@/components/library/primitives/HoverButton'
import { cn } from '@/lib/utils'

export type BannerImmersiveProps = {
  image: { src: string; alt: string }
  title: string
  eyebrow?: string
  symbol?: ReactNode
  description?: string
  actions?: readonly { label: string; href: string; variant?: 'primary' | 'light' | 'outline' }[]
  align?: 'left' | 'center'
  height?: 'screen' | 'large'
  overlay?: 'light' | 'medium' | 'strong'
  className?: string
}

const overlays = {
  light: 'bg-black/25',
  medium: 'bg-black/45',
  strong: 'bg-black/65',
}

/** Banner fotográfico de tela cheia — sem navbar; combine com um componente de Navbars. */
export function BannerImmersive({
  image,
  title,
  eyebrow,
  symbol,
  description,
  actions = [],
  align = 'center',
  height = 'large',
  overlay = 'medium',
  className,
}: BannerImmersiveProps) {
  return (
    <section
      className={cn(
        'relative isolate overflow-hidden bg-slate-950 text-white',
        height === 'screen' ? 'min-h-screen' : 'min-h-[680px]',
        className,
      )}
      aria-labelledby="banner-immersive-title"
    >
      <Image src={image.src} alt={image.alt} fill priority className="object-cover" sizes="100vw" />
      <div className={cn('absolute inset-0', overlays[overlay])} />
      <div className="absolute inset-x-0 top-0 h-40 bg-gradient-to-b from-black/60 to-transparent" />

      <div
        className={cn(
          'container relative z-10 flex items-center py-20',
          height === 'screen' ? 'min-h-screen' : 'min-h-[680px]',
          align === 'center' ? 'justify-center text-center' : 'justify-start text-left',
        )}
      >
        <div className={cn('max-w-4xl', align === 'center' && 'flex flex-col items-center')}>
          {symbol ? <div className="mb-6 text-white">{symbol}</div> : null}
          {eyebrow ? (
            <p className="mb-4 text-xs font-bold uppercase tracking-[0.25em] text-white/70">
              {eyebrow}
            </p>
          ) : null}
          <h1
            id="banner-immersive-title"
            className="text-5xl font-bold tracking-tight sm:text-6xl lg:text-8xl"
          >
            {title}
          </h1>
          {description ? (
            <p className="mt-6 max-w-2xl text-base leading-8 text-white/75 sm:text-lg">
              {description}
            </p>
          ) : null}
          {actions.length ? (
            <div className="mt-9 flex flex-wrap gap-3">
              {actions.map((action) => (
                <HoverButton
                  key={`${action.label}-${action.href}`}
                  href={action.href}
                  effect={action.variant === 'outline' ? 'glow' : 'lift'}
                  variant={action.variant === 'primary' ? 'default' : 'secondary'}
                  size="lg"
                  className={cn(
                    'rounded-full',
                    action.variant === 'outline' &&
                      'border border-white/40 bg-transparent text-white hover:bg-white/10',
                  )}
                >
                  {action.label}
                </HoverButton>
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </section>
  )
}

import { cn } from '@/lib/utils'

/** Logo oficial Bloomin (PNG embutido para funcionar no catálogo e nos projetos instalados). */
const BLOOMIN_LOGO_SRC =
  'data:image/png;base64,'

export const BLOOMIN_URL = 'https://bloomin.com.br'

export type BloominLogoProps = {
  className?: string
  /** Altura visual do logo (largura acompanha a proporção). */
  height?: number
}

export function BloominLogo({ className, height = 18 }: BloominLogoProps) {
  return (
    // eslint-disable-next-line @next/next/no-img-element -- data URI portátil no registry
    <img
